 useEffect(()=>{const client=supabase;if(!client)return;let active=true;const load=async()=>{const args={p_latitude:userCoords?.lat??null,p_longitude:userCoords?.lon??null,p_radius_km:radius,p_category_key:category==='all'?null:category,p_search_text:query.trim()||null};const {data,error}=await client.rpc('search_nearby_businesses',args);if(!active||error||!data)return;const mapped:Provider[]=data.map((b:any)=>{const ss=(b.services||[]).filter((x:any)=>x.is_active!==false);const cat=b.category_key==='barber'?'barber':b.category_key==='salon'?'salon':b.category_key;return{id:Number(b.business_id),categoryKey:cat,name:b.name_ar||b.name_fr||'Service',type:cat==='barber'?'حلاق رجالي':cat==='salon'?'صالون حلاقة':'خدمات',typeFr:cat==='barber'?'Barbier':cat==='salon'?'Salon de coiffure':'Services',area:b.address_ar||b.city||'تونس',areaFr:b.address_fr||b.city||'Tunis',distance:typeof b.distance_km==='number'?b.distance_km:999,rating:0,reviews:0,price:ss.length?Number(ss[0].price||0):0,next:'حسب التوفّر',nextFr:'Selon disponibilité',image:'https://images.unsplash.com/photo-1503951914875-452162b0f3f1?auto=format&fit=crop&w=700&q=85',cover:'',services:ss.map((x:any)=>x.name_ar),verified:Boolean(b.verified),online:true,live:true,serviceDetails:ss};});setProviderData(mapped);};void load();return()=>{active=false};},[userCoords,radius,category,query]);
